begin;
select plan(33);
select has_table('public','surgical_checklist_templates','facility checklist templates are stored');
select has_table('public','surgical_checklist_instances','checklists are instantiated per procedure');
select has_table('public','surgical_checklist_answers','checklist responses are attributed');
select has_table('public','surgical_checklist_completions','completion is an audited event');
select has_table('public','surgery_anaesthesia_events','anaesthesia and handover events are recorded');
select has_table('public','surgery_recovery_observations','recovery observations are recorded');
select has_table('public','surgery_consumable_reconciliations','consumable counts are reconciled');
select has_column('public','surgical_checklist_templates','items','facility templates hold configurable JSON items');
select has_column('public','surgery_anaesthesia_events','free_text','agent and dose entries preserve free-text');
select has_column('public','surgery_anaesthesia_events','agent_name','agent is also structured');
select has_column('public','surgery_anaesthesia_events','dose','dose is also structured');
select has_function('public','set_surgical_checklist_template',array['uuid','text','jsonb'],'facility configures empty-by-default checklist templates');
select has_function('public','create_surgical_checklist_instance',array['uuid','text'],'procedure gets a snapshot checklist instance');
select has_function('public','answer_surgical_checklist_item',array['uuid','text','boolean','text'],'checklist answers are recorded by an authorized user');
select has_function('public','complete_surgical_checklist',array['uuid'],'required answers are validated before completion');
select has_function('public','add_surgery_anaesthesia_event',array['uuid','text','jsonb'],'pre-assessment, intraoperative, and recovery handover are recorded');
select has_function('public','record_surgery_anaesthesia_agent',array['uuid','text','text','numeric','text','text','timestamp with time zone'],'agent, dose, route, unit, time, and free-text are recorded');
select has_function('public','add_surgery_recovery_observation',array['uuid','jsonb'],'recovery room observations are appended');
select has_function('public','reconcile_surgery_consumable',array['uuid','text','integer','integer','text'],'consumable count differences require an explanation');
select has_trigger('public','surgeries','guard_surgery_workflow','status transitions retain a server-side checklist guard');
select has_trigger('public','surgical_checklist_answers','surgical_checklist_answers_immutable','answers cannot be rewritten or removed');
select has_trigger('public','surgery_anaesthesia_events','surgery_anaesthesia_events_immutable','anaesthesia entries cannot be rewritten or removed');
select ok(not has_table_privilege('authenticated','public.surgical_checklist_answers','INSERT'),'clients cannot bypass checklist answer RPC');
select ok(not has_table_privilege('authenticated','public.surgery_anaesthesia_events','INSERT'),'clients cannot bypass anaesthesia recording RPC');
select ok(not has_table_privilege('authenticated','public.surgical_checklist_templates','UPDATE'),'clients cannot bypass facility template RPC');
select like(pg_get_functiondef('public.guard_surgery_workflow()'::regprocedure),'%pre-induction and time-out checklists before starting surgery%','in-progress transition requires pre-induction and time-out completion');
select like(pg_get_functiondef('public.guard_surgery_workflow()'::regprocedure),'%sign-out checklists before completing surgery%','completed transition requires sign-out completion');
select like(pg_get_functiondef('public.guard_surgery_workflow()'::regprocedure),'%new.status is distinct from old.status%','gate applies specifically to status transitions');
select like(pg_get_functiondef('public.create_surgical_checklist_instance(uuid,text)'::regprocedure),'%Facility has not configured a non-empty template%','empty default templates fail closed');
select like(pg_get_functiondef('public.complete_surgical_checklist(uuid)'::regprocedure),'%Every required checklist item must have a current confirmed answer%','unanswered or unconfirmed required items block completion');
select like(pg_get_functiondef('public.record_surgery_anaesthesia_agent(uuid,text,text,numeric,text,text,timestamp with time zone)'::regprocedure),'%Free-text note, agent, non-negative dose, dose unit, route, and administration time are required%','structured agent entries require all fields');
select like(pg_get_functiondef('public.reconcile_surgery_consumable(uuid,text,integer,integer,text)'::regprocedure),'surgery_consumable_reconciliations','count reconciliation is persisted in an append-only table');
select has_check('public','surgery_consumable_reconciliations','surgery_consumable_reconciliations_check','count discrepancies must be explained');
select * from finish();
rollback;
